using System.Text.Json;
using System.Text.Json.Nodes;
using Yukkuri.Simulation;

// Focused component fixtures deliberately seed readiness and pregnancy progress.
// The separately recorded default public journey establishes reachability.
int failures=0,checks=0;
void Require(bool ok,string message){if(!ok)throw new Exception(message);}
void Check(string name,Action test){checks++;try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e);}}
void Tick(WorldSimulation s,double seconds){for(int n=0;n<(int)Math.Round(seconds*20);n++){s.AdvanceInteractionPresentation(.05);s.Advance(.05);}}
string Json(WorldSimulation s)=>JsonSerializer.Serialize(s.State,SaveStore.JsonOptions);
WorldSimulation Copy(WorldSimulation s){var state=JsonSerializer.Deserialize<WorldState>(Json(s),SaveStore.JsonOptions)!;SaveStore.Validate(state);return new(state);}
Creature M(WorldSimulation s)=>s.State.Creatures[0];
Creature A(WorldSimulation s)=>s.State.Creatures[1];
Creature B(WorldSimulation s)=>s.State.Creatures[2];
Creature C(WorldSimulation s)=>s.State.Creatures[3];
WorldSimulation Fixture(ulong seed=1)
{
 var s=WorldSimulation.CreateCourtyardEconomy(unchecked(seed*11400714819323198485UL));s.SetAutonomousBreeding(false);s.State.RoomObjects.Clear();
 var extra=JsonSerializer.Deserialize<Creature>(JsonSerializer.Serialize(B(s),SaveStore.JsonOptions),SaveStore.JsonOptions)!;
 extra.Id="recovery-source-C";extra.Body.Id="recovery-body-C";extra.Registration.IdentityId="recovery-identity-C";extra.Interaction.Accessory.Id="recovery-accessory-C";extra.Family=new();s.State.Creatures.Add(extra);
 for(int n=0;n<s.State.Creatures.Count;n++){
  var c=s.State.Creatures[n];c.IsYoung=false;c.Body.AgeSeconds=c.InnerAgeSeconds=2000;c.Body.ReproductionRole=n==0?ReproductionRole.Maternal:ReproductionRole.Paternal;
  c.Fullness=c.Energy=c.Interaction.Hydration=c.Health=100;c.Trust=90;c.Fear=c.Pain=c.Resentment=0;c.Aggression=.1;c.Patience=.5;c.Courage=.2;
  c.X=c.TargetX=n==0?0:n==1?-5:5;c.Z=c.TargetZ=n==3?5:0;c.Interaction.NextAutonomyAt=10000;c.Interaction.ToyInterest=0;c.Family.NextSocialAt=c.Family.NextCareAt=10000;
 }
 SaveStore.Validate(s.State);return s;
}
void Recover(WorldSimulation s,params string[] ids){M(s).Family.Pregnancy=new(){Phase=PregnancyPhase.Recovering,Method=BirthMethod.Stem,FatherId=ids.LastOrDefault(),RecoveryRemaining=100,RecoveryFatherIds=ids.ToList()};}
void Force(WorldSimulation s,Creature f){Require(s.CollectBreedingMaterial(f.Id).Contains("已保存"),"collection failed");string result=s.RequestForcedPregnancy(M(s).Id,f.Id,BirthMethod.Stem);Require(FamilyRules.UnderIntervention(M(s)),result);}
void Sources(WorldSimulation s,params string[] ids){Require(M(s).Family.Pregnancy.RecoveryFatherIds.Order().SequenceEqual(ids.Order()),"wrong recovery identity set");}
void Locked(WorldSimulation s,Creature c,bool expected){string before=Json(s);string? reason=s.CreatureSaleReason(c.Id);Require((reason=="请等待这次孕育与恢复结束，再出售相关亲油。")==expected,"wrong recovery lock: "+reason);Require(Json(s)==before,"query mutated state");if(expected){int money=s.State.Money;s.SellCreatureToShop(c.Id,CourtyardEconomy.Quote(c).Price);Require(Json(s)==before&&s.State.Money==money,"blocked sale mutated state");}}
void EndThroughFailure(WorldSimulation s,Creature f){var p=M(s).Family.Pregnancy;p.Phase=PregnancyPhase.Gestating;p.Method=BirthMethod.Live;p.Stem=null;p.FatherId=f.Id;p.EventId="recovery-event-"+(++s.State.FamilySequence);p.PlannedChildren=1;p.InterventionRemaining=0;p.Burden=80;p.NextDecisionAt=10000;M(s).Fullness=10;Tick(s,.25);Require(p.Phase==PregnancyPhase.Recovering,"pregnancy failure did not settle");}
JsonObject Pregnancy(JsonObject root)=>root["Creatures"]![0]!["Family"]!["Pregnancy"]!.AsObject();
WorldState Parse(JsonObject root)=>JsonSerializer.Deserialize<WorldState>(root.ToJsonString(),SaveStore.JsonOptions)!;
void Reject(JsonObject root){try{SaveStore.Validate(Parse(root));throw new Exception("invalid save accepted");}catch(InvalidDataException){}}

Check("A recovery survives B preparation and cancellation, B is released",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));Sources(s,A(s).Id);Locked(s,A(s),true);Locked(s,B(s),true);double debt=M(s).Family.Pregnancy.RecoveryDebt;s.InterruptPregnancyIntervention(M(s).Id);Sources(s,A(s).Id);Require(M(s).Family.Pregnancy.RecoveryRemaining==debt,"changed recovery time");Locked(s,A(s),true);Locked(s,B(s),false);Copy(s);});
Check("B preparation body interruption preserves A only",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));M(s).Interaction.Supine=true;Tick(s,.25);Require(!FamilyRules.UnderIntervention(M(s)),"not interrupted");Sources(s,A(s).Id);Locked(s,A(s),true);Locked(s,B(s),false);Copy(s);});
Check("random failed and successful interventions preserve A before B outcome",()=>{bool success=false,failure=false;for(ulong seed=1;seed<=64&&(!success||!failure);seed++){var s=Fixture(seed);Recover(s,A(s).Id);Force(s,B(s));Tick(s,4.25);var p=M(s).Family.Pregnancy;Sources(s,A(s).Id);Locked(s,A(s),true);if(p.Phase==PregnancyPhase.Gestating){success=true;Locked(s,B(s),true);EndThroughFailure(s,B(s));Sources(s,A(s).Id,B(s).Id);}else{failure=true;Require(p.Phase==PregnancyPhase.Recovering,"unexpected failure phase");Locked(s,B(s),false);}Copy(s);}Require(success&&failure,"missing random branch");});
Check("failed B gestation adds B; A+B survive C preparation and cancel",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));EndThroughFailure(s,B(s));Sources(s,A(s).Id,B(s).Id);M(s).Fullness=M(s).Energy=M(s).Interaction.Hydration=100;M(s).Family.NextForcedAttemptAt=0;Force(s,C(s));Locked(s,A(s),true);Locked(s,B(s),true);Locked(s,C(s),true);s.InterruptPregnancyIntervention(M(s).Id);Sources(s,A(s).Id,B(s).Id);Locked(s,C(s),false);Copy(s);});
Check("successful B birth adds B without replacing A",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));var p=M(s).Family.Pregnancy;p.Phase=PregnancyPhase.Gestating;p.Method=BirthMethod.Live;p.EventId="recovery-success";p.PlannedChildren=1;p.InterventionRemaining=0;p.Elapsed=479.9;p.Burden=0;Tick(s,.5);Require(s.State.CompletedBirths.Contains("recovery-success")&&p.Phase==PregnancyPhase.Recovering,"actual delivery did not complete");Sources(s,A(s).Id,B(s).Id);Copy(s);});
Check("same-father overlap stays deduplicated",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,A(s));EndThroughFailure(s,A(s));Sources(s,A(s).Id);Copy(s);});
Check("no-debt cancellation releases the unbegun father",()=>{var s=Fixture();Force(s,B(s));s.InterruptPregnancyIntervention(M(s).Id);Sources(s);Require(M(s).Family.Pregnancy.Phase==PregnancyPhase.None,"cancel created recovery");Locked(s,B(s),false);Copy(s);});
Check("recovery expiry clears all accumulated sources",()=>{var s=Fixture();Recover(s,A(s).Id,B(s).Id);M(s).Family.Pregnancy.RecoveryRemaining=.1;Tick(s,.25);Sources(s);Require(M(s).Family.Pregnancy.Phase==PregnancyPhase.None,"not expired");Locked(s,A(s),false);Locked(s,B(s),false);Copy(s);});
Check("actual death cleanup clears sources",()=>{var s=Fixture();Recover(s,A(s).Id,B(s).Id);s.State.Settings.LethalInjuries=true;var m=M(s);m.Condition=PhysicalCondition.Critical;m.Health=0;m.CriticalRemaining=.1;m.Interaction.Injuries.CriticalCareBudget=.1;m.Interaction.Injuries.CriticalEpisode=true;Tick(s,.25);Require(m.Condition==PhysicalCondition.Dead,"death did not occur");Sources(s);Locked(s,A(s),false);Locked(s,B(s),false);Copy(s);});
Check("independent detached brood still blocks its father after maternal recovery expires",()=>{var s=Fixture();Require(s.BuyShopProduct("scissors"),"scissors purchase failed");var p=M(s).Family.Pregnancy;p.Phase=PregnancyPhase.Gestating;p.Method=BirthMethod.Stem;p.FatherId=A(s).Id;p.EventId="independent-brood";p.PlannedChildren=2;p.Elapsed=37;p.Stem=new(){EventId=p.EventId};var input=new InteractionInput(InteractionAction.CutStem,ObjectId:p.EventId,TargetKind:InteractionTargetKind.Stem);Require(s.BeginInteractionGesture(M(s).Id,input).Success,"cut rejected");for(int n=0;n<20;n++)s.ContinueInteractionGesture(input,true);s.EndInteractionGesture();Require(s.State.DetachedStemBroods.Count==1,"cut did not detach");p.RecoveryRemaining=.1;Tick(s,.25);Sources(s);Locked(s,A(s),true);Copy(s);});
Check("fresh disk round trips preserve None, Preparing, Gestating and Recovering",()=>{string dir=Path.Combine(Path.GetTempPath(),"yukkuri-recovery-"+Guid.NewGuid().ToString("N"));var store=new SaveStore(dir);var s=Fixture();for(int n=0;n<4;n++){if(n==1){Recover(s,A(s).Id);Force(s,B(s));}if(n==2){var p=M(s).Family.Pregnancy;p.Phase=PregnancyPhase.Gestating;p.EventId="disk-gestation";p.PlannedChildren=2;p.InterventionRemaining=0;}if(n==3)EndThroughFailure(s,B(s));store.Save(s.State,n);var loaded=store.Load(n).State;Require(JsonSerializer.Serialize(loaded,SaveStore.JsonOptions)==Json(s),"disk load changed state at phase "+n);}Console.WriteLine("Disk snapshots retained for audit.");});
Check("new property is empty by default and marker never serialized",()=>{var p=new PregnancyState();Require(p.RecoveryFatherIds.Count==0,"new instance inherited sources");string json=JsonSerializer.Serialize(p,SaveStore.JsonOptions);Require(json.Contains("\"RecoveryFatherIds\": []")&&!json.Contains("Present")&&!json.Contains("_recovery"),"private marker leaked");});
Check("missing legacy ordinary recovery migrates regardless of JSON property order",()=>{var s=Fixture();Recover(s,A(s).Id);var root=JsonNode.Parse(Json(s))!.AsObject();var p=Pregnancy(root);p.Remove("RecoveryFatherIds");var reordered=new JsonObject();foreach(var pair in p.Reverse())reordered.Add(pair.Key,pair.Value?.DeepClone());root["Creatures"]![0]!["Family"]!["Pregnancy"]=reordered;var state=Parse(root);SaveStore.Validate(state);Require(state.Creatures[0].Family.Pregnancy.RecoveryFatherIds.SequenceEqual(new[]{A(s).Id}),"legacy source not migrated");});
Check("explicit empty legacy-compatible list never fabricates a source",()=>{var s=Fixture();Recover(s,A(s).Id);M(s).Family.Pregnancy.RecoveryFatherIds.Clear();var copy=Copy(s);Sources(copy);Locked(copy,A(copy),false);});
Check("missing old overlapping preparing and gestating cannot recover lost A",()=>{foreach(var phase in new[]{PregnancyPhase.Preparing,PregnancyPhase.Gestating}){var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));if(phase==PregnancyPhase.Gestating){var p=M(s).Family.Pregnancy;p.Phase=phase;p.EventId="old-gestating";p.PlannedChildren=2;p.InterventionRemaining=0;}var root=JsonNode.Parse(Json(s))!.AsObject();Pregnancy(root).Remove("RecoveryFatherIds");var state=Parse(root);SaveStore.Validate(state);Require(state.Creatures[0].Family.Pregnancy.RecoveryFatherIds.Count==0,"invented unknown old source");}});
Check("old forced cancelled recovery never misidentifies unbegun B",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));s.InterruptPregnancyIntervention(M(s).Id);var root=JsonNode.Parse(Json(s))!.AsObject();Pregnancy(root).Remove("RecoveryFatherIds");var state=Parse(root);SaveStore.Validate(state);Require(state.Creatures[0].Family.Pregnancy.RecoveryFatherIds.Count==0,"invented cancelled B source");});
Check("reject null, blank, unknown, self and duplicate recovery references",()=>{var s=Fixture();Recover(s,A(s).Id);foreach(var value in new JsonNode?[]{null,new JsonArray((string?)null),new JsonArray(""),new JsonArray(" "),new JsonArray("missing"),new JsonArray(M(s).Id),new JsonArray(A(s).Id,A(s).Id)}){var root=JsonNode.Parse(Json(s))!.AsObject();Pregnancy(root)["RecoveryFatherIds"]=value;Reject(root);}});
Check("reject nonempty sources detached from recovery time",()=>{var s=Fixture();Recover(s,A(s).Id);foreach(var phase in new[]{PregnancyPhase.None,PregnancyPhase.Recovering,PregnancyPhase.Preparing}){var root=JsonNode.Parse(Json(s))!.AsObject();var p=Pregnancy(root);p["Phase"]=phase.ToString();p["RecoveryRemaining"]=0;p["RecoveryDebt"]=0;Reject(root);}});
Check("historical dead and changed-body father references remain valid",()=>{var s=Fixture();Recover(s,A(s).Id);A(s).Body.ReproductionRole=ReproductionRole.Maternal;Copy(s);A(s).Condition=PhysicalCondition.Dead;A(s).Health=0;Copy(s);});
Check("known sold father reference remains valid without resurrecting it",()=>{var s=Fixture();string father=B(s).Id;int price=CourtyardEconomy.Quote(B(s)).Price;s.SellCreatureToShop(father,price);Require(s.State.CreatureSales.Count==1,"fixture sale failed");Recover(s,father);Copy(s);});
if(args.Length>0)Check("genuine baseline public saves migrate only recoverable identity",()=>{foreach(string name in new[]{"ordinary-recovering","overlap-preparing","overlap-cancelled"}){var state=JsonSerializer.Deserialize<WorldState>(File.ReadAllText(Path.Combine(args[0],name+".json")),SaveStore.JsonOptions)!;SaveStore.Validate(state);var p=state.Creatures[0].Family.Pregnancy;Require(name=="ordinary-recovering"?p.RecoveryFatherIds.SequenceEqual(new[]{state.Creatures[1].Id}):p.RecoveryFatherIds.Count==0,"genuine legacy migration wrong: "+name);}});
Check("old missing None, zero clock and missing father never fabricate history",()=>{foreach(int variation in new[]{0,1,2}){var s=Fixture();Recover(s,A(s).Id);var root=JsonNode.Parse(Json(s))!.AsObject();var p=Pregnancy(root);p.Remove("RecoveryFatherIds");if(variation==0){p["Phase"]="None";p["RecoveryRemaining"]=0;p["RecoveryDebt"]=100;}if(variation==1)p["FatherId"]=null;if(variation==2)p["RecoveryRemaining"]=0;var state=Parse(root);SaveStore.Validate(state);Require(state.Creatures[0].Family.Pregnancy.RecoveryFatherIds.Count==0,"fabricated absent source");}});
Check("world reconstruction keeps the persisted recovery set and sale guards",()=>{var s=Fixture();Recover(s,A(s).Id);Force(s,B(s));var restored=Copy(s);Sources(restored,A(s).Id);Locked(restored,A(restored),true);Locked(restored,B(restored),true);restored.InterruptPregnancyIntervention(M(restored).Id);restored=Copy(restored);Sources(restored,A(s).Id);Locked(restored,A(restored),true);Locked(restored,B(restored),false);});
if(args.Length>0)Check("real old forced recovery retains its known completed source only",()=>{var state=JsonSerializer.Deserialize<WorldState>(File.ReadAllText(Path.Combine(args[0],"forced-event-recovering.json")),SaveStore.JsonOptions)!;SaveStore.Validate(state);var p=state.Creatures[0].Family.Pregnancy;Require(p.Forced&&p.EventId!=null&&p.Phase==PregnancyPhase.Recovering&&p.RecoveryFatherIds.SequenceEqual(new[]{p.FatherId!}),"real forced recovery source lost");});
Console.WriteLine($"CHECKS {checks}; FAILURES {failures}");return failures==0?0:1;